  "version": "0.1.0",
  "valid": true,
  "difficulties": [
   {
    "id": "yanyi",
    "label": "演义",
    "description": "宽和之局。范阳异志滋长较慢，流言少，府库稍丰，诏令少有稽迟。适合初识天宝局势。",
    "default": false
   },
   {
    "id": "shishi",
    "label": "史实",
    "description": "依史事设定的常例。明君善处可弭兵祸，然鼙鼓之声中局必起，须时时经营。",
    "default": true
   },
   {
    "id": "diyu",
    "label": "地狱",
    "description": "多事之秋。异志与鼙鼓增势更急，流言倍起，君威易损，府库开局即紧，诏令多有稽迟。",
    "default": false
   }
  ]
 }
]

